import{_ as d,C as i,o as s,c as u,j as e,a as n,E as l,a3 as o}from"./chunks/framework.D4-ViStF.js";const y=JSON.parse('{"title":"杂卦传","description":"以对举方式点明各卦要义之传——用极简的卦德互照六十四卦，建立从序卦到逐卦阅读的复习入口。","frontmatter":{"title":"杂卦传","description":"以对举方式点明各卦要义之传——用极简的卦德互照六十四卦，建立从序卦到逐卦阅读的复习入口。","category":"guide","aliases":["杂卦传","杂卦","za gua zhuan"],"source":["《周易·杂卦传》"]},"headers":[],"relativePath":"yijing/shi-yi/za-gua-zhuan.md","filePath":"yijing/shi-yi/za-gua-zhuan.md","lastUpdated":1788516578000}'),c={name:"yijing/shi-yi/za-gua-zhuan.md"};function p(m,a,g,b,q,x){const r=i("DaoReadingPrelude"),t=i("DaoTextReading"),h=i("DaoKeywordCards");return s(),u("div",null,[a[0]||(a[0]=e("h1",{id:"杂卦传",tabindex:"-1"},[n("杂卦传 "),e("a",{class:"header-anchor",href:"#杂卦传","aria-label":'Permalink to "杂卦传"'},"​")],-1)),l(r,{title:"把六十四卦放在对照中读",summary:"《杂卦传》篇幅极短，却把六十四卦放进一面关系之镜：乾刚坤柔，比乐师忧，震起艮止，损益见盛衰，既济定而未济穷。它不沿着序卦讲一条路，而是用对举和极简卦德，让每一卦最突出的气质彼此照见。",points:[{label:"先读字",text:"先看每一卦被压缩成的一个字，感受《杂卦》的凝练。"},{label:"再看对",text:"把刚柔、乐忧、聚升、内外、损益等放在一起，看差异如何显义。"},{label:"后回卦",text:"最后回到具体卦页，用这一个字作入口，不把它当成一卦全部的定义。"}],hint:"《序卦》像一条路，说明卦为何相承；《杂卦》像一面镜，照出卦最鲜明的一面。两篇合读，六十四卦才既有次序，也有层次。"}),a[1]||(a[1]=o('<h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>《杂卦传》不按《序卦传》的顺序讲卦，而是将六十四卦错杂、对举，用一两个字点出各卦最突出的卦德与关系。</p><p>「杂」不是杂乱，也不是把卦义随意打散；它更像一种错综阅读：把相反、相成或相互映照的卦放到一起，让读者在差异中看见一卦之「要」。</p><p>这里要特别保留一个边界：**《杂卦》所说的是一卦之要，不是一卦之尽。**乾不只有刚，坤不只有柔；困不只是困顿，井也不只是通达。</p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><ul><li>它是十翼中最浓缩的卦德索引，适合建立六十四卦的第一层记忆。</li><li>对举本身就是方法：刚与柔、乐与忧、内与外、损与益，能帮助读者看到卦义的边界。</li><li>它可以作为逐卦阅读的开头标签，再回到卦辞、彖辞、象辞中验证和展开。</li><li>与《序卦传》一纵一横：序卦说明「为什么这样排」，杂卦提示「这一卦最显什么」。</li></ul><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先完整读一遍，不急着记住全部，只感受极简语言的节奏。</li><li>再圈出对举关系：乾坤、比师、震艮、损益、否泰、家人睽、离坎等。</li><li>遇到不熟的字，先看本页释义，再回到对应卦页观察卦辞与卦德是否互相印证。</li><li>不把一个字当作固定标签。问一卦「此处为何取这个要义」，也问它还有哪些没有被写出的层次。</li><li>最后与《序卦传》对读：一个看变化的承接，一个看意义的对照。</li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>刚柔相待</strong>：乾刚坤柔，不是高下判断，而是创始、担当与承载、成全的两种力量。</li><li><strong>关系有乐有忧</strong>：比乐师忧，说明亲比合作之外，还有组织、责任、纪律和共同面对困难的忧患。</li><li><strong>动止相济</strong>：震起艮止；有力量时要知道收住，环境不宜时要知道退守。</li><li><strong>损益见盛衰</strong>：损益不是简单的减少和增加，而是盛衰开始显现的地方。</li><li><strong>剥复与晋夷</strong>：剥为烂、复为反；晋如昼、明夷为伤，衰败中有回归，前进中也要护住光明。</li><li><strong>内外与通塞</strong>：家人内、睽外，否泰反其类；内在关系与外在环境会彼此转化。</li><li><strong>革鼎取新</strong>：革去旧故，鼎取新器；破旧之后还要建立能够承载的新秩序。</li><li><strong>既济未济</strong>：既济为定，未济为穷；完成是阶段，不是变化的终点。</li></ul><h2 id="与六十四卦的联动" tabindex="-1">与六十四卦的联动 <a class="header-anchor" href="#与六十四卦的联动" aria-label="Permalink to &quot;与六十四卦的联动&quot;">​</a></h2><ul><li>逐卦阅读入口：<a href="/Dao/yijing/hexagrams/"><code>六十四卦目录</code></a>。可将《杂卦》的定调字作为每一卦的第一张阅读卡片。</li><li>与<a href="/Dao/yijing/shi-yi/xu-gua-zhuan"><code>序卦传</code></a>对读：序卦看前后因果，杂卦看相对卦德。</li><li>重点回看 <code>hexagram-01</code>（乾）、<code>hexagram-02</code>（坤）、<code>hexagram-11</code>（泰）、<code>hexagram-12</code>（否）、<code>hexagram-63</code>（既济）、<code>hexagram-64</code>（未济）。</li><li>「艮止」「巽伏」「中孚信」等卦德，也可与<a href="/Dao/yijing/shi-yi/shuo-gua-zhuan"><code>说卦传</code></a>的基本卦德互相参照。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>',13)),l(t,{colophon:"刚柔对举 · 卦德互照 · 一字定调 · 既济未济",tone:"ink",sections:[{id:"duan-01",sentences:[["《乾》刚，《坤》柔；《比》乐，《师》忧；《临》《观》之义，或与或求。"],["《屯》见而不失其居，《蒙》杂而著；《震》，起也，《艮》，止也。"],["《损》《益》，盛衰之始也；《大畜》，时也；《无妄》，灾也。"],["《萃》聚而《升》不来也，《谦》轻而《豫》怠也；《噬嗑》，食也，《贲》，无色也。"],["《兑》见而《巽》伏也，《随》无故也，《蛊》则饬也；《剥》，烂也，《复》，反也。"]]},{id:"duan-02",sentences:[["《晋》，昼也；《明夷》，诛也；《井》通而《困》相遇也；《咸》速也。"],["《恒》，久也；《涣》，离也；《节》，止也；《解》，缓也；《蹇》，难也。"],["《睽》，外也；《家人》，内也；《否》《泰》，反其类也；《大壮》则止，《遁》则退也。"],["《大有》，众也；《同人》，亲也；《革》，去故也；《鼎》，取新也；《小过》，过也；《中孚》，信也。"],["《丰》，多故也；亲寡《旅》也。《离》上而《坎》下也；《小畜》，寡也；《履》，不处也；《需》，不进也。"]]},{id:"duan-03",sentences:[["《讼》，不亲也；《大过》，颠也；《姤》，遇也，柔遇刚也；《渐》，女归待男行也。"],["《颐》，养正也；《既济》，定也；《归妹》，女之终也；《未济》，男之穷也。"],["《夬》，决也，刚决柔也。君子道长，小人道忧也。"]]}],"aria-label":"杂卦传原文"}),a[2]||(a[2]=e("blockquote",null,[e("p",null,"注：本页采用你提供的通行本文字整理。不同底本在「诛／伤」「萃聚而升不来也」等字词、句读和解释上可能有异文；其中「女之终」「男之穷」带有古代阴阳与婚姻秩序的语境，现代阅读时应区分其结构象征与现实规范。")],-1)),a[3]||(a[3]=e("h2",{id:"【原典层】字词释义",tabindex:"-1"},[n("【原典层】字词释义 "),e("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),l(h,{items:[{term:"杂卦",pinyin:["zá","guà"],meaning:"错杂、错综地排列卦义，以对举和互照的方式提示各卦之要。杂不是杂乱，而是换一种关系视角。"},{term:"卦德",pinyin:["guà","dé"],meaning:"一卦所呈现的主要性质、功能或倾向。「刚」「柔」「起」「止」「信」等都是高度压缩的卦德提示。"},{term:"对举",pinyin:["duì","jǔ"],meaning:"把相反或相成的两种状态放在一起说明。对举不是简单二选一，而是让一方照见另一方的边界。"},{term:"或与或求",pinyin:["yǔ","qiú"],meaning:"临有与、给予、接近的一面，观有求、观察、仰观的一面，写出关系中给予与学习的两种姿态。"},{term:"不失其居",pinyin:["bù","shī","qí","jū"],meaning:"在屯难、萌动与显现中不失去自己的根基和位置。初始阶段不宜只求扩张，更要先稳住居处。"},{term:"饬",pinyin:["chì"],meaning:"整饬、修治。「蛊则饬」说明积弊显现后不能只维持表面和气，而要认真整理和修复。"},{term:"反其类",pinyin:["fǎn","qí","lèi"],meaning:"否与泰性质相反，却可以彼此转化；通塞、盛衰都不是永恒停留的类别。"},{term:"取新",pinyin:["qǔ","xīn"],meaning:"鼎所代表的建立新器、承载新秩序。革去旧故之后，还需要有新的制度、能力和方法接续。"},{term:"中孚",pinyin:["zhōng","fú"],meaning:"内在诚信、中心真实。「信」不只在宏大承诺，也体现在小处的谨慎与持续兑现。"},{term:"既济",pinyin:["jì","jì"],meaning:"已经渡过、事情暂时完成。「定」是阶段性安定，并不意味着变化从此停止。"},{term:"未济",pinyin:["wèi","jì"],meaning:"尚未渡过、尚未完成。「穷」指当前阶段未能抵达，并保留继续变化、继续行动的可能。"}]}),a[4]||(a[4]=o('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><blockquote><p>本节将《杂卦》的极简句子还原为阅读方法：先看它点出的卦德，再观察它与对照卦的关系，最后回到具体处境。</p></blockquote><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>《杂卦传》像一册六十四卦的极简索引。它不解释每卦的全部层次，只从丰富的卦义中挑出一处最适合与别卦相映照的重点：乾刚、坤柔；震起、艮止；损益见盛衰；革去故、鼎取新；中孚为信，既济为定。</p><p>它把卦从线性次序中暂时取出，放进一张关系网络。读者看到的不是「先后发生什么」，而是「两种力量放在一起时，各自显出什么」。</p><h3 id="理-为什么一个字也能打开一卦" tabindex="-1">理：为什么一个字也能打开一卦 <a class="header-anchor" href="#理-为什么一个字也能打开一卦" aria-label="Permalink to &quot;理：为什么一个字也能打开一卦&quot;">​</a></h3><ul><li>极简不是把复杂问题粗暴简化，而是先给出一个入口，供读者回到原卦继续展开。</li><li>对举不是制造绝对二分。刚需要柔来承载，乐中要有忧患，止之后还会再起，完成之后仍然未济。</li><li>卦德必须放回时位和关系中理解。同一个「进」在不同位置，可能是晋，也可能因为过度而成大过。</li><li>《杂卦》与《说卦》都重卦德，但说卦偏向建立八卦的基本意，《杂卦》则将六十四卦放进更复杂的互照网络。</li></ul><h3 id="用-今天怎么使用这面镜子" tabindex="-1">用：今天怎么使用这面镜子 <a class="header-anchor" href="#用-今天怎么使用这面镜子" aria-label="Permalink to &quot;用：今天怎么使用这面镜子&quot;">​</a></h3><p>遇到一件事时，可以先用一个字给当前状态定调，再主动寻找它的对面：</p><ul><li>我现在是在「起」还是在「止」？是在「损」以远害，还是「益」而过满？</li><li>我是在《比》的亲近中，还是承担《师》的责任？是在《丰》的多故中，还是《旅》的亲寡中？</li><li>我面对的是《革》的旧问题，还是已经准备好用《鼎》承接新局？</li></ul><p>这个过程不是用卦名替现实下结论，而是借一个高度凝练的词，把分散的感觉重新组织起来，再检查它是否与具体关系、位置和行动相应。</p><h2 id="【解读层】分段解读" tabindex="-1">【解读层】分段解读 <a class="header-anchor" href="#【解读层】分段解读" aria-label="Permalink to &quot;【解读层】分段解读&quot;">​</a></h2><h3 id="一、刚柔与关系-从乾坤到临观" tabindex="-1">一、刚柔与关系：从乾坤到临观 <a class="header-anchor" href="#一、刚柔与关系-从乾坤到临观" aria-label="Permalink to &quot;一、刚柔与关系：从乾坤到临观&quot;">​</a></h3><p>乾刚坤柔是全篇的起点。刚可以开创、决断、担当，柔可以承载、调和、成全；两者不是价值高下，而是两种互补的力量。</p><p>比乐师忧把这种互补推进到关系与共同体：亲比令人喜悦，但组织众人、承担任务便有忧患。临观则提示关系中的给予与求取：有时需要靠近、照看和承担，有时需要观察、学习和求助。</p><h3 id="二、初生与行动-屯蒙、震艮、损益" tabindex="-1">二、初生与行动：屯蒙、震艮、损益 <a class="header-anchor" href="#二、初生与行动-屯蒙、震艮、损益" aria-label="Permalink to &quot;二、初生与行动：屯蒙、震艮、损益&quot;">​</a></h3><p>屯是初生的艰难，见而不失其居，说明新事物显现时仍要守住根基；蒙是杂而渐著，说明初学的混杂可以通过养与教逐步显明。</p><p>震起、艮止是一组最直接的行动提醒。只会起而不会止，容易耗散；只会止而不再起，则会停滞。损益又告诉我们，增减本身就是盛衰开始显现的地方，眼前的多和少都要放回长期趋势观察。</p><h3 id="三、随蛊、剥复与晋明夷-顺境、衰败和光明" tabindex="-1">三、随蛊、剥复与晋明夷：顺境、衰败和光明 <a class="header-anchor" href="#三、随蛊、剥复与晋明夷-顺境、衰败和光明" aria-label="Permalink to &quot;三、随蛊、剥复与晋明夷：顺境、衰败和光明&quot;">​</a></h3><p>随可以是无故的自然相从，蛊则是顺从和惯性积久后的积弊，必须整饬。剥是腐烂、剥落，复是返回、回到根本；这组对照说明衰败不是唯一结局，但回转也不是回到过去假装无事。</p><p>晋如昼，明夷则是光明受伤。前进和显明值得珍惜，却不能忘记环境、位置和风险；有时要在白昼中前行，有时要先护住内在的明。</p><h3 id="四、通塞与人伦-井困、咸恒、睽家人" tabindex="-1">四、通塞与人伦：井困、咸恒、睽家人 <a class="header-anchor" href="#四、通塞与人伦-井困、咸恒、睽家人" aria-label="Permalink to &quot;四、通塞与人伦：井困、咸恒、睽家人&quot;">​</a></h3><p>井通而困相遇，说明供养与受阻是现实中相邻的两种状态；升而不已会困，困于上又要反下，回到基础和井的持续供养。</p><p>咸速、恒久，把瞬间感应与长期关系放在一起；涣离、节止、解缓、蹇难，则提醒过紧需要松，过散需要节，有难时不可妄进。</p><p>家人内、睽外，写亲近关系的内部秩序与对外的乖离。内外并非固定标签，家道失调会生睽，外在受伤也会反求于家。</p><h3 id="五、革鼎与既济未济-改变、承载与开放结尾" tabindex="-1">五、革鼎与既济未济：改变、承载与开放结尾 <a class="header-anchor" href="#五、革鼎与既济未济-改变、承载与开放结尾" aria-label="Permalink to &quot;五、革鼎与既济未济：改变、承载与开放结尾&quot;">​</a></h3><p>革是去故，鼎是取新。改变不能只停在否定旧物，还要建立新的器物、习惯、制度和承载能力。小过与中孚则说明，小处的谨慎和真实的诚信，是新秩序能够长久的基础。</p><p>既济是定，事情暂时完成；未济是穷，尚未抵达。篇末没有把世界封在一个圆满结局里，而是留下继续变化的门：完成之后仍要维护，未完成也仍有下一步。</p><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>有些书像地图，告诉我们事情从哪里走到哪里；《杂卦传》更像一组镜片，把同一世界中的不同气质放在一起。刚与柔、起与止、乐与忧、内与外、损与益，彼此对照之后，原本模糊的状态才有了轮廓。</p><p>一个字不是答案，而是入口。说「损」，还要问损掉什么、为了什么；说「困」，还要问困在什么位置、是否需要反下求井；说「既济」，还要问完成是否真的稳固；说「未济」，也不能因此认定事情没有希望。</p><p>所以读《杂卦》，是在练习一种不孤立看事的能力：看到一面，也主动寻找另一面；看到成，也保留未成；看到顺，也记得可能的忧患。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>《杂卦》给我的第一个提醒，是不要让一个标签替代真实观察。卦德可以帮助我把问题收拢，但收拢之后还要回到卦象、时位、关系和行动中验证。</p><p>第二个提醒，是对照比单独定义更有力量。人很容易只想要「乐」而回避「忧」，只想「起」而不愿「止」，只想「益」而不肯「损」；把两面放在一起，才更接近变化中的完整。</p><p>第三个提醒，是既济与未济的收尾。事情做完时不必过度兴奋，事情未成时也不必过早绝望。完成只是一个暂时的定，未完成则仍保留新的行动空间。</p><h2 id="延伸阅读-参考来源" tabindex="-1">延伸阅读 / 参考来源 <a class="header-anchor" href="#延伸阅读-参考来源" aria-label="Permalink to &quot;延伸阅读 / 参考来源&quot;">​</a></h2><ul><li>上一篇：<a href="/Dao/yijing/shi-yi/xu-gua-zhuan"><code>序卦传</code></a></li><li>十翼总览：<a href="/Dao/yijing/shi-yi/"><code>孔子十翼</code></a></li><li>相关原典：<a href="/Dao/yijing/shi-yi/shuo-gua-zhuan"><code>说卦传</code></a></li><li>六十四卦目录：<a href="/Dao/yijing/hexagrams/"><code>文王六十四卦</code></a></li><li>通行本《周易·杂卦传》（王弼注、孔颖达疏系统）</li></ul>',38))])}const _=d(c,[["render",p]]);export{y as __pageData,_ as default};
